with valid as (select id, customer_id, plan, start_date, end_date, monthly_fee, status, case when plan in ('premium', 'basic') then 'Priority' else 'Other' end as plan_group, length(plan) as plan_length from subscriptions where customer_id is not null) select case when plan_length >= 80 then 'HIGH' else 'LOW' end as plan_length_tier, count_if(status = 'ACTIVE') as active_events, count(*) as row_count, sum(monthly_fee) as total_monthly_fee, percentile_approx(monthly_fee, 0.9) as monthly_fee_p90, size(collect_set(plan)) as num_plans from valid group by 1;
